# UTF-8. Technical PNG preparation only; artwork is generated by image_gen.
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;
public static class WolfPng {
  static byte[] Pixels(Bitmap b) {
    var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
    byte[] p=new byte[b.Width*b.Height*4]; Marshal.Copy(d.Scan0,p,0,p.Length); b.UnlockBits(d); return p;
  }
  static Bitmap FromPixels(byte[] p,int w,int h) {
    var b=new Bitmap(w,h,PixelFormat.Format32bppArgb);
    var d=b.LockBits(new Rectangle(0,0,w,h), ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
    Marshal.Copy(p,0,d.Scan0,p.Length);b.UnlockBits(d);return b;
  }
  public static Bitmap Load(string path) {
    using(var s=new Bitmap(path)) {var b=new Bitmap(s.Width,s.Height,PixelFormat.Format32bppArgb);
      using(var g=Graphics.FromImage(b)){g.CompositingMode=CompositingMode.SourceCopy;g.DrawImageUnscaled(s,0,0);} return b;}
  }
  public static Bitmap Clean(Bitmap b) {
    int w=b.Width,h=b.Height,n=w*h; var p=Pixels(b);var seen=new bool[n];var largest=new List<int>();
    int[] q=new int[n];
    for(int start=0;start<n;start++) {
      if(seen[start]||p[start*4+3]<128) continue;
      int first=0,last=0;q[last++]=start;seen[start]=true;var comp=new List<int>();
      while(first<last) {int v=q[first++];comp.Add(v);int x=v%w,y=v/w;
        for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){
          int xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=w||yy>=h)continue;
          int u=yy*w+xx;if(!seen[u]&&p[u*4+3]>=128){seen[u]=true;q[last++]=u;}
        }
      }
      if(comp.Count>largest.Count)largest=comp;
    }
    var mask=new bool[n];foreach(int v in largest)mask[v]=true;
    var outp=(byte[])p.Clone();
    for(int v=0;v<n;v++) {
      int x=v%w,y=v/w,a=p[v*4+3];bool near=false,inside=true;int nearest=-1,best=99;
      for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){
        int xx=x+dx,yy=y+dy;bool on=xx>=0&&yy>=0&&xx<w&&yy<h&&mask[yy*w+xx];
        if(!on)inside=false;
        else {near=true;int dist=dx*dx+dy*dy;if(dist<best){best=dist;nearest=yy*w+xx;}}
      }
      if(!near||a==0) {outp[v*4]=outp[v*4+1]=outp[v*4+2]=outp[v*4+3]=0;continue;}
      if(!mask[v] && a>=128){outp[v*4+3]=0;continue;}
      outp[v*4+3]=(byte)(inside?255:a);
      if(a<255&&nearest>=0){for(int c=0;c<3;c++)outp[v*4+c]=p[nearest*4+c];}
    }
    return FromPixels(outp,w,h);
  }
  public static Rectangle Bounds(Bitmap b,int threshold) {
    var p=Pixels(b);int x0=b.Width,y0=b.Height,x1=-1,y1=-1;
    for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(p[(y*b.Width+x)*4+3]>=threshold){
      x0=Math.Min(x0,x);y0=Math.Min(y0,y);x1=Math.Max(x1,x);y1=Math.Max(y1,y);
    }return Rectangle.FromLTRB(x0,y0,x1+1,y1+1);
  }
  public static void Prepare(string src,string dst) {
    using(var raw=Load(src))using(var cleaned=Clean(raw)) {
      var bb=Bounds(cleaned,1);int hh=1200,ww=(int)Math.Round(bb.Width*hh/(double)bb.Height);
      using(var canvas=new Bitmap(1536,1536,PixelFormat.Format32bppArgb)) {
        using(var g=Graphics.FromImage(canvas)) {
          g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.HighQualityBicubic;
          g.PixelOffsetMode=PixelOffsetMode.HighQuality;
          using(var attr=new ImageAttributes()){attr.SetWrapMode(WrapMode.TileFlipXY);
            g.DrawImage(cleaned,new Rectangle((1536-ww)/2,168,ww,hh),bb.X,bb.Y,bb.Width,bb.Height,GraphicsUnit.Pixel,attr);}
        }
        using(var final=Clean(canvas)) final.Save(dst,ImageFormat.Png);
      }
    }
  }
  public static string Report(string path) {
    using(var b=Load(path)){
      var p=Pixels(b);int zero=0,full=0,partial=0,deep=0;var bb=Bounds(b,1);
      for(int v=0;v<b.Width*b.Height;v++){
        int a=p[v*4+3];if(a==0)zero++;else if(a==255)full++;else{
          partial++;bool hasOutside=false,hasInside=false;int x=v%b.Width,y=v/b.Width;
          for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int xx=x+dx,yy=y+dy;
            if(xx<0||yy<0||xx>=b.Width||yy>=b.Height){hasOutside=true;continue;}
            int aa=p[(yy*b.Width+xx)*4+3];if(aa<128)hasOutside=true;else hasInside=true;
          }if(!hasOutside||!hasInside)deep++;
        }
      }
      return String.Format("size={0}x{1}; bbox=[{2},{3},{4},{5}]; height={6}; alpha0={7}; alpha255={8}; alpha1to254={9}; partial_outside_2px_boundary={10}; corners={11}/{12}/{13}/{14}",
        b.Width,b.Height,bb.X,bb.Y,bb.Right,bb.Bottom,bb.Height,zero,full,partial,deep,
        b.GetPixel(0,0).A,b.GetPixel(b.Width-1,0).A,b.GetPixel(0,b.Height-1).A,b.GetPixel(b.Width-1,b.Height-1).A);
    }
  }
  public static void Contact(string[] paths,string dst) {
    const int cw=760,ch=1030;double scale=.55;
    using(var board=new Bitmap(cw*paths.Length,ch,PixelFormat.Format24bppRgb))
    using(var g=Graphics.FromImage(board))
    using(var font=new Font("Arial",22,FontStyle.Bold))
    using(var small=new Font("Arial",14)) {
      g.Clear(Color.FromArgb(234,229,222));g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
      string[] labels={"A - CLAY TOY WEREWOLF","B - FERAL WEREWOLF","WITCH A - IDENTITY","NIB v03 - STYLE","BEASTFOLK - DIFFERENTIATE"};
      g.DrawString("WITCH'S LODGE / WEREWOLF v01",font,Brushes.DimGray,24,18);
      g.DrawString("Same pixel scale: 55% | Feet aligned | No per-character height normalization",small,Brushes.DimGray,24,55);
      g.DrawLine(Pens.Silver,0,920,board.Width,920);
      for(int i=0;i<paths.Length;i++){
        using(var b=Load(paths[i])) {
          var bb=Bounds(b,128);float ww=(float)(bb.Width*scale),hh=(float)(bb.Height*scale);
          g.InterpolationMode=InterpolationMode.HighQualityBicubic;
          g.DrawImage(b,new RectangleF(i*cw+(cw-ww)/2,920-hh,ww,hh),bb,GraphicsUnit.Pixel);
          g.DrawString(labels[i],small,Brushes.Black,i*cw+24,955);
          g.DrawString("Source alpha height: "+bb.Height+" px",small,Brushes.DimGray,i*cw+24,984);
        }
      }
      board.Save(dst,ImageFormat.Png);
    }
  }
}
'@
$dest = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
[WolfPng]::Prepare((Join-Path $PSScriptRoot 'werewolf-a-proportion-final.png'),(Join-Path $dest 'werewolf-3q-a-v01.png'))
[WolfPng]::Prepare((Join-Path $PSScriptRoot 'werewolf-b-selected.png'),(Join-Path $dest 'werewolf-3q-b-v01.png'))
$project = [IO.Path]::GetFullPath((Join-Path $dest '../../../../'))
$paths = @(
  (Join-Path $dest 'werewolf-3q-a-v01.png'),
  (Join-Path $dest 'werewolf-3q-b-v01.png'),
  (Join-Path $project 'art/concepts/characters/witch-north-model-v01/witch-3q-a-v01.png'),
  (Join-Path $project 'art/concepts/characters/goblin-nib-model-v03/nib-3q-v03.png'),
  (Join-Path $project 'art/concepts/characters/beastfolk-common-model-v02/beastfolk-common-3q-v02.png')
)
[WolfPng]::Contact($paths,(Join-Path $dest 'werewolf-v01-contact.png'))
foreach($p in $paths) { Write-Output ($p + ': ' + [WolfPng]::Report($p)) }
Get-ChildItem -LiteralPath $dest -Recurse -File | Where-Object Extension -EQ '.png' | ForEach-Object {Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256 | Select-Object Path,Hash} | ConvertTo-Json
